cat > trie_graph.cpp << 'EOF'
#include "trie_graph.h"

#include <algorithm>
#include <map>

uint32_t ni_position(const PrefixRec& p, int depth) {
    int l = p.len - depth;
    if (l < 0) l = 0;
    if (l > 5) l = 5;
    return (1u << l) + static_cast<uint32_t>(get_bits(p.addr, depth, l));
}

namespace {

GNode* build_node(Graph& g, const std::vector<PrefixRec>& s, int origin, int max_len,
                  const ip6_t& region, int level) {
    const int depth = origin + 6 * level;
    GNode* n = new GNode();
    g.owned.push_back(n);
    n->origin = origin;
    n->level = level;
    n->depth = depth;
    n->max_len = max_len;
    n->region = region;

    if (s.size() <= 2) {                       // TYPE4 / TYPE5 leaf
        n->type = (s.size() == 1) ? 4 : 5;
        n->pfx = s;
        return n;
    }

    std::vector<PrefixRec> local;
    std::vector<PrefixRec> buckets[64];
    for (size_t i = 0; i < s.size(); ++i) {
        const PrefixRec& p = s[i];
        if (p.len < depth + 6) local.push_back(p);
        else buckets[get_bits(p.addr, depth, 6)].push_back(p);
    }

    std::sort(local.begin(), local.end(),
              [depth](const PrefixRec& a, const PrefixRec& b) {
                  return ni_position(a, depth) < ni_position(b, depth);
              });
    n->pfx = local;
    n->ni_count = static_cast<uint32_t>(local.size());
    for (size_t i = 0; i < local.size(); ++i)
        n->ni_bitmap |= 1ULL << ni_position(local[i], depth);

    for (int k = 0; k < 64; ++k) {
        if (buckets[k].empty()) continue;
        ip6_t cr = region;
        or_bits(cr, depth, static_cast<uint64_t>(k), 6);
        n->children.push_back(build_node(g, buckets[k], origin, max_len, cr, level + 1));
        n->keys.push_back(static_cast<uint8_t>(k));
    }

    const int c = static_cast<int>(n->children.size());
    n->type = (c <= 2) ? 1 : (c <= 6 ? 2 : 3);
    return n;
}

} // namespace

Graph build_graph(const std::vector<PrefixRec>& fib_in) {
    Graph g;

    std::vector<PrefixRec> fib = fib_in;
    for (size_t i = 0; i < fib.size(); ++i) mask_prefix(fib[i].addr, fib[i].len);
    std::sort(fib.begin(), fib.end());
    fib.erase(std::unique(fib.begin(), fib.end(),
                          [](const PrefixRec& a, const PrefixRec& b) {
                              return a.addr == b.addr && a.len == b.len;
                          }),
              fib.end());

    PrefixTrie trie;
    for (size_t i = 0; i < fib.size(); ++i)
        trie.insert(fib[i].addr, fib[i].len, fib[i].hop);

    std::vector<PrefixRec> g0;
    std::map<uint64_t, std::vector<PrefixRec>> m16, m64;
    for (size_t i = 0; i < fib.size(); ++i) {
        const PrefixRec& p = fib[i];
        if (p.len <= 16) g0.push_back(p);
        else if (p.len <= 64) m16[p.addr.hi >> 48].push_back(p);
        else m64[p.addr.hi].push_back(p);
    }

    if (!g0.empty()) {
        ip6_t region;
        g.root0 = build_node(g, g0, 0, 16, region, 0);
    }
    for (std::map<uint64_t, std::vector<PrefixRec>>::iterator it = m16.begin();
         it != m16.end(); ++it) {
        ip6_t region;
        region.hi = it->first << 48;
        g.front16.push_back(std::make_pair(it->first,
                                           build_node(g, it->second, 16, 64, region, 0)));
    }
    for (std::map<uint64_t, std::vector<PrefixRec>>::iterator it = m64.begin();
         it != m64.end(); ++it) {
        ip6_t region;
        region.hi = it->first;
        g.front64.push_back(std::make_pair(it->first,
                                           build_node(g, it->second, 64, 128, region, 0)));
    }

    // Global BMP: longest FIB prefix of length <= node depth that covers the
    // whole node region.  It may come from any forest.
    for (size_t i = 0; i < g.owned.size(); ++i) {
        GNode* n = g.owned[i];
        int32_t h = trie.longest_match(n->region, n->depth);
        n->bmp = (h < 0) ? HOP_NULL : static_cast<uint32_t>(h);
    }
    return g;
}
